def find(nums, x):
    lo, hi = 0, len(nums)          # the answer is in positions lo .. hi-1
    while lo < hi:
        mid = (lo + hi) // 2
        print(f"  look at position {mid} (value {nums[mid]}), range {lo}..{hi - 1}")
        if nums[mid] == x:
            return mid
        if nums[mid] < x:
            lo = mid + 1            # mid is too small: drop it and everything left of it
        else:
            hi = mid                # mid is too big: hi is excluded, so hi = mid drops it
    return -1

