import numpy as np

def mse(y, y_pred):
    y, y_pred = np.asarray(y, float), np.asarray(y_pred, float)
    return float(np.mean((y - y_pred) ** 2))

def r2(y, y_pred):
    y, y_pred = np.asarray(y, float), np.asarray(y_pred, float)
    return float(1 - np.sum((y - y_pred) ** 2) / np.sum((y - y.mean()) ** 2))

def ols(X, y):
    Xb = np.column_stack([np.ones(len(X)), X])
    w, *_ = np.linalg.lstsq(Xb, y, rcond=None)
    return w

def gd_step(w, X, y, lr):
    n = len(y)
    return w - lr * (2 / n) * X.T @ (X @ w - y)

