import numpy as np

def error_report(y_true, y_pred):
    t, p = np.asarray(y_true, float), np.asarray(y_pred, float)
    return {'mae': float(np.mean(np.abs(t - p))),
            'mape': float(np.mean(np.abs(t - p) / np.abs(t)))}

