def flatten_config(d, sep="/", prefix=""):
    out = {}
    for k, v in d.items():
        key = f"{prefix}{sep}{k}" if prefix else str(k)
        if isinstance(v, dict):
            out.update(flatten_config(v, sep, key))
        else:
            out[key] = v
    return out

