def top_tags(data, n, chars="#.,!? ", upper=False):
    # 1. string or list? Make sure we end up with a list
    if isinstance(data, str):
        raw_tags = data.split()
    else:
        raw_tags = data

    # 2. clean each tag and keep the non-empty ones
    tags = []
    for tag in raw_tags:
        tag = tag.strip(chars)
        if upper:
            tag = tag.upper()
        else:
            tag = tag.lower()
        if tag:
            tags.append(tag)

    # 3. count each tag
    counts = {}
    for tag in tags:
        counts[tag] = counts.get(tag, 0) + 1

    # 4. sort, then keep the first n
